def deep_merge(base: dict, override: dict) -> dict:
"""
Return a deep-merged copy of base and override.

Override values take precedence. Nested dictionaries are merged
recursively, while non-dictionary values are replaced directly.

Example:
    >>> deep_merge(
    ...     {"database": {"host": "localhost", "port": 5432}, "debug": False},
    ...     {"database": {"port": 5433}, "debug": True}
    ... )
    {'database': {'host': 'localhost', 'port': 5433}, 'debug': True}
"""
from copy import deepcopy

result = deepcopy(base)

for key, override_value in override.items():
    base_value = result.get(key)

    if isinstance(base_value, dict) and isinstance(override_value, dict):
        result[key] = deep_merge(base_value, override_value)
    else:
        result[key] = deepcopy(override_value)

return result

def merge_config(base: dict, override: dict) -> dict:
"""Backward-compatible wrapper for canonical deep configuration merging."""
return deep_merge(base, override)
